// Normaliza cada linha e agrupa por paciente + dia
const raw = $input.all();

// Protecao contra BOM: quando o CSV e salvo pelo Excel/LibreOffice, um
// caractere invisivel as vezes gruda no nome da PRIMEIRA coluna do cabecalho
// (ex: nome_paciente vira algo ilegivel), fazendo o campo sumir mesmo com
// o dado preenchido no arquivo. Essa funcao acha o campo certo mesmo assim.
function campo(obj, chave) {
  if (obj[chave] !== undefined) return obj[chave];
  const chaveEncontrada = Object.keys(obj).find(k => k.replace(/^\uFEFF/, '').trim() === chave);
  return chaveEncontrada ? obj[chaveEncontrada] : '';
}
function normalizaTelefone(tel) {
  if (!tel) return '';
  let digits = String(tel).replace(/\D/g, '');
  if (digits.length === 11) digits = '55' + digits;
  else if (digits.length === 10) digits = '55' + digits;
  return digits;
}

const mapaServicos = {
  '10101012': 'Consulta médica',
  '40101010': 'ECG - Eletrocardiograma',
  '40101037': 'Teste Ergométrico',
  '40901106': 'Ecocardiograma Doppler Transtorácico',
  '40901360': 'Ecocardiograma Doppler de Carótidas e Vertebrais'
};

function nomeServicoAmigavel(servicoBruto) {
  const codigo = String(servicoBruto || '').split('-')[0].trim();
  if (mapaServicos[codigo]) return mapaServicos[codigo];

  // Fallback por palavra-chave: cobre MAPA/Holter e qualquer servico novo
  // sem depender de eu conhecer o codigo de faturamento exato.
  const texto = String(servicoBruto || '').toUpperCase();
  if (texto.includes('MAPA')) return 'MAPA 24 horas';
  if (texto.includes('HOLTER')) return 'Holter 24 horas';
  if (texto.includes('ERGOM')) return 'Teste Ergométrico';
  if (texto.includes('CAROT') || texto.includes('VASOS CERVICAIS')) return 'Ecocardiograma Doppler de Carótidas e Vertebrais';
  if (texto.includes('TRANSTORAC')) return 'Ecocardiograma Doppler Transtorácico';
  if (texto.includes('ECG') || texto.includes('ELETROCARDIOGRAMA')) return 'ECG - Eletrocardiograma';
  if (texto.includes('CONSULTA')) return 'Consulta médica';

  return servicoBruto || 'Atendimento';
}
// Verifica se o valor do campo medico_responsavel e um nome de medico de
// verdade, ou um placeholder (ECG, MAPA, Holter, sem preferencia, etc.)
// que na pratica significa "sem medico definido para este atendimento".
function medicoValido(medicoBruto, servicoAmigavel) {
  if (!medicoBruto) return false;
  const m = medicoBruto.trim().toUpperCase();
  const placeholders = [
    'ECG', 'MAPA', 'HOLTER',
    'SEM PREFERENCIA', 'SEM PREFERÊNCIA', 'SEM PREFERENCIA MEDICA', 'SEM PREFERÊNCIA MÉDICA',
    'A DEFINIR', 'NAO DEFINIDO', 'NÃO DEFINIDO', 'INDIFERENTE', 'QUALQUER', 'QUALQUER MEDICO', 'QUALQUER MÉDICO',
    '-', 'N/A', 'NA'
  ];
  if (placeholders.includes(m)) return false;
  if (m === String(servicoAmigavel || '').toUpperCase()) return false;
  return true;
}
function formataHora(hora) {
  const h = String(hora || '').replace(/\D/g, '');
  if (h.length === 4) return `${h.slice(0,2)}:${h.slice(2)}`;
  return hora;
}

const grupos = {};

for (const item of raw) {
  const j = item.json;
  const nome = String(campo(j, 'nome_paciente') || '').trim();
  const telefoneOriginal = String(j.telefone_whatsapp || '').trim();
  const data = String(j.data_consulta || '').trim();
  const horaBruta = String(j.hora_consulta_exame || '').trim();
  const medicoBruto = String(j.medico_responsavel || '').trim();
  const servico = nomeServicoAmigavel(j.servico);

  const telefone = normalizaTelefone(telefoneOriginal);
  if (!telefone || telefone.length < 12) continue; // sem telefone valido = bloqueio interno de agenda

  // linhas marcadas como "Retorno" (prazo de retorno sem cobrar nova consulta) nao sao
  // pacientes agendados de verdade - descarta mesmo que por engano venha com telefone
  if (nome.trim().toUpperCase() === 'RETORNO') continue;

  const chave = `${telefone}_${data}`;
  if (!grupos[chave]) grupos[chave] = { chave, telefone, nome, data, itens: [] };

  const medico = medicoValido(medicoBruto, servico) ? medicoBruto : null;
  grupos[chave].itens.push({ hora: formataHora(horaBruta), medico, servico });
}

const resultado = Object.values(grupos).map(g => {
  g.itens.sort((a, b) => a.hora.localeCompare(b.hora));
  return g;
});

return resultado.map(g => ({ json: g }));

return $input.all().map(item => {
  const g = item.json;
  const linhas = g.itens.map(it => {
    const medicoTexto = it.medico ? ` com ${it.medico}` : '';
    return `- ${it.hora} - ${it.servico}${medicoTexto}`;
  });
  const primeiroNome = (g.nome || '').split(' ')[0] || 'Paciente';
  const mensagem = `Ola, ${primeiroNome}! Aqui e da Clinica Cardiocenter.\n\nConfirmando seu agendamento para o dia ${g.data}:\n${linhas.join('\n')}\n\nPor favor responda:\n1 - Confirmo minha presenca\n2 - Preciso remarcar ou cancelar`;
  const resumo = linhas.join(' | ');
  return { json: { ...g, mensagem, resumo } };
});
